import { jest } from '@jest/globals';

const playerPath = '../../../../sisyphus/src/player.js';
const scenePath = '../../../../sisyphus/src/scene.js';
const terrainPath = '../../../../sisyphus/src/terrain.js';
const inputPath = '../../../../sisyphus/src/input.js';

const WALK_SPEED = 4.5;
const SPRINT_SPEED = 7.5;
const PUSH_SPEED = 2.0;
const PUSH_SPRINT_SPEED = 3.5;
const JUMP_FORCE = 9;
const GRAVITY = 22;

/**
 * Builds a fresh player module with deterministic collaborators. updatePlayer
 * keeps module-level state, so each test gets its own module instance.
 */
async function createPlayer({
  input: inputOverrides = {},
  groundHeight = () => 0,
  stamina = { current: 100, canSprint: true },
  cameraYaw = () => 0,
  boulderRef = null,
} = {}) {
  const input = {
    forward: false,
    back: false,
    left: false,
    right: false,
    sprint: false,
    jump: false,
    ...inputOverrides,
  };
  const scene = { add: jest.fn() };
  const getHeightAt = jest.fn(groundHeight);
  const getStamina = jest.fn(() => stamina);
  const getCameraYaw = jest.fn(cameraYaw);
  const getBoulderRef = jest.fn(() => boulderRef);

  jest.resetModules();
  jest.unstable_mockModule(scenePath, () => ({ getScene: () => scene }));
  jest.unstable_mockModule(terrainPath, () => ({ getHeightAt }));
  jest.unstable_mockModule(inputPath, () => ({ input }));

  const player = await import(playerPath);
  player.initPlayer();
  player.setPlayerDependencies(getStamina, getCameraYaw, getBoulderRef);

  return {
    player,
    input,
    scene,
    stamina,
    getHeightAt,
    getStamina,
    getCameraYaw,
    getBoulderRef,
    setInput(overrides) {
      Object.assign(input, overrides);
    },
  };
}

describe('updatePlayer', () => {
  describe('horizontal movement', () => {
    test.each([
      ['forward', { forward: true }, 0, -WALK_SPEED],
      ['back', { back: true }, 0, WALK_SPEED],
      ['left', { left: true }, -WALK_SPEED, 0],
      ['right', { right: true }, WALK_SPEED, 0],
    ])('maps %s input to a walking velocity at yaw zero', async (_name, input, expectedX, expectedZ) => {
      const harness = await createPlayer({ input });

      harness.player.updatePlayer(0.1);

      expect(harness.player.getPlayerVelocity().x).toBeCloseTo(expectedX, 10);
      expect(harness.player.getPlayerVelocity().z).toBeCloseTo(expectedZ, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.WALK);
      expect(harness.player.getPlayerPosition().x).toBeCloseTo(expectedX * 0.1, 10);
      expect(harness.player.getPlayerPosition().z).toBeCloseTo(2 + expectedZ * 0.1, 10);
    });

    test('normalizes diagonal input so it does not move faster than a cardinal direction', async () => {
      const harness = await createPlayer({ input: { forward: true, right: true } });

      harness.player.updatePlayer(0.1);

      const velocity = harness.player.getPlayerVelocity();
      const component = WALK_SPEED / Math.SQRT2;
      expect(velocity.x).toBeCloseTo(component, 10);
      expect(velocity.z).toBeCloseTo(-component, 10);
      expect(Math.hypot(velocity.x, velocity.z)).toBeCloseTo(WALK_SPEED, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.WALK);
    });

    test('rotates movement direction by the camera yaw', async () => {
      const harness = await createPlayer({
        input: { forward: true },
        cameraYaw: () => Math.PI / 2,
      });

      harness.player.updatePlayer(0.1);

      expect(harness.player.getPlayerVelocity().x).toBeCloseTo(-WALK_SPEED, 10);
      expect(harness.player.getPlayerVelocity().z).toBeCloseTo(0, 10);
      expect(harness.player.getPlayerPosition().x).toBeCloseTo(-0.45, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.WALK);
    });

    test('turns to face the movement direction over time', async () => {
      const harness = await createPlayer({ input: { forward: true } });

      harness.player.updatePlayer(0.1);

      const expectedFacing = Math.PI * (1 - Math.exp(-1));
      expect(harness.player.getPlayerFacing()).toBeCloseTo(expectedFacing, 10);
    });

    test('treats opposing direction keys as no movement input', async () => {
      const harness = await createPlayer({ input: { forward: true, back: true } });
      harness.player.getPlayerVelocity().set(4, 0, -2);

      harness.player.updatePlayer(0.2);

      expect(harness.player.getPlayerVelocity().x).toBe(0);
      expect(harness.player.getPlayerVelocity().z).toBe(0);
      expect(harness.player.getPlayerPosition().x).toBe(0);
      expect(harness.player.getPlayerPosition().z).toBe(2);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.IDLE);
    });

    test('decelerates while preserving the decelerated movement for this frame', async () => {
      const harness = await createPlayer();
      harness.player.getPlayerVelocity().set(4, 0, -2);

      harness.player.updatePlayer(0.05);

      expect(harness.player.getPlayerVelocity().x).toBeCloseTo(1.6, 10);
      expect(harness.player.getPlayerVelocity().z).toBeCloseTo(-0.8, 10);
      expect(harness.player.getPlayerPosition().x).toBeCloseTo(0.08, 10);
      expect(harness.player.getPlayerPosition().z).toBeCloseTo(1.96, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.WALK);
    });
  });

  describe('speed selection and state', () => {
    test('uses sprint speed and sprint state when stamina allows sprinting', async () => {
      const harness = await createPlayer({ input: { forward: true, sprint: true } });

      harness.player.updatePlayer(0.1);

      expect(harness.player.getPlayerVelocity().z).toBeCloseTo(-SPRINT_SPEED, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.SPRINT);
    });

    test('falls back to walking when stamina forbids sprinting', async () => {
      const harness = await createPlayer({
        input: { forward: true, sprint: true },
        stamina: { current: 80, canSprint: false },
      });

      harness.player.updatePlayer(0.1);

      expect(harness.player.getPlayerVelocity().z).toBeCloseTo(-WALK_SPEED, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.WALK);
    });

    test('uses push speed and push state while pushing', async () => {
      const harness = await createPlayer({ input: { forward: true } });
      harness.player.setPlayerPushing(true);

      harness.player.updatePlayer(0.1);

      expect(harness.player.getPlayerVelocity().z).toBeCloseTo(-PUSH_SPEED, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.PUSH);
    });

    test('uses push-sprint speed and state while sprinting with the boulder', async () => {
      const harness = await createPlayer({ input: { forward: true, sprint: true } });
      harness.player.setPlayerPushing(true);

      harness.player.updatePlayer(0.1);

      expect(harness.player.getPlayerVelocity().z).toBeCloseTo(-PUSH_SPRINT_SPEED, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.PUSH_SPRINT);
    });

    test('reports exhausted state when a pushing player has no stamina left', async () => {
      const harness = await createPlayer({
        input: { forward: true, sprint: true },
        stamina: { current: 0, canSprint: true },
      });
      harness.player.setPlayerPushing(true);

      harness.player.updatePlayer(0.1);

      // Movement still uses the requested speed for this frame, but the state
      // machine gives exhaustion precedence over push-sprinting.
      expect(harness.player.getPlayerVelocity().z).toBeCloseTo(-PUSH_SPRINT_SPEED, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.EXHAUSTED);
    });

    test('reports idle when stationary', async () => {
      const harness = await createPlayer();

      harness.player.updatePlayer(0.1);

      expect(harness.player.getPlayerVelocity().length()).toBe(0);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.IDLE);
    });
  });

  describe('jumping and gravity', () => {
    test('applies the jump impulse, gravity, and an airborne state', async () => {
      const harness = await createPlayer({ input: { jump: true } });
      const dt = 0.016;

      harness.player.updatePlayer(dt);

      const expectedVerticalVelocity = JUMP_FORCE - GRAVITY * dt;
      expect(harness.player.getPlayerVelocity().y).toBeCloseTo(expectedVerticalVelocity, 10);
      expect(harness.player.getPlayerPosition().y).toBeCloseTo(expectedVerticalVelocity * dt, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.AIRBORNE);
    });

    test('continues applying gravity while airborne', async () => {
      const harness = await createPlayer({ input: { jump: true } });
      harness.player.updatePlayer(0.1);
      const velocityAfterJump = harness.player.getPlayerVelocity().y;
      const yAfterJump = harness.player.getPlayerPosition().y;

      harness.setInput({ jump: false });
      harness.player.updatePlayer(0.1);

      expect(harness.player.getPlayerVelocity().y).toBeCloseTo(velocityAfterJump - GRAVITY * 0.1, 10);
      expect(harness.player.getPlayerPosition().y).toBeCloseTo(
        yAfterJump + (velocityAfterJump - GRAVITY * 0.1) * 0.1,
        10,
      );
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.AIRBORNE);
    });

    test('does not reapply the jump impulse before landing', async () => {
      const harness = await createPlayer({ input: { jump: true } });
      harness.player.updatePlayer(0.1);
      const firstFrameVelocity = harness.player.getPlayerVelocity().y;

      harness.player.updatePlayer(0.1);

      expect(harness.player.getPlayerVelocity().y).toBeCloseTo(firstFrameVelocity - GRAVITY * 0.1, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.AIRBORNE);
    });

    test('lands on the terrain and clears vertical velocity', async () => {
      const harness = await createPlayer({ input: { jump: true } });

      harness.player.updatePlayer(0.5);

      expect(harness.player.getPlayerPosition().y).toBe(0);
      expect(harness.player.getPlayerVelocity().y).toBe(0);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.IDLE);
    });

    test('ignores jump input while pushing', async () => {
      const harness = await createPlayer({ input: { jump: true } });
      harness.player.setPlayerPushing(true);

      harness.player.updatePlayer(0.1);

      expect(harness.player.getPlayerVelocity().y).toBe(0);
      expect(harness.player.getPlayerPosition().y).toBe(0);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.PUSH);
    });

    test('airborne state takes precedence over pushing and exhaustion', async () => {
      const harness = await createPlayer({ input: { jump: true } });
