      });
      harness.player.getPlayerPosition().x = 0.9;

      harness.player.updatePlayer(0.1);

      const expectedY = -0.2 * (1 - Math.exp(-2));
      expect(harness.player.getPlayerPosition().x).toBeCloseTo(1.35, 10);
      expect(harness.player.getPlayerPosition().y).toBeCloseTo(expectedY, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.WALK);
