    forward: false,
    back: false,
    left: false,
    right: false,
    sprint: false,
    jump: false,
    ...inputOverrides,
  };
  const scene = { add: jest.fn() };
  const getHeightAt = jest.fn(groundHeight);
  const getStamina = jest.fn(() => stamina);
  const getCameraYaw = jest.fn(cameraYaw);
  const getBoulderRef = jest.fn(() => boulderRef);

  jest.resetModules();
  jest.unstable_mockModule(scenePath, () => ({ getScene: () => scene }));
  jest.unstable_mockModule(terrainPath, () => ({ getHeightAt }));
  jest.unstable_mockModule(inputPath, () => ({ input }));

  const player = await import(playerPath);
  player.initPlayer();
  player.setPlayerDependencies(getStamina, getCameraYaw, getBoulderRef);

  return {
    player,
    input,
    scene,
    stamina,
    getHeightAt,
    getStamina,
    getCameraYaw,
