      expect(harness.player.getPlayerVelocity().z).toBeCloseTo(expectedZ, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.WALK);
      expect(harness.player.getPlayerPosition().x).toBeCloseTo(expectedX * 0.1, 10);
      expect(harness.player.getPlayerPosition().z).toBeCloseTo(2 + expectedZ * 0.1, 10);
