      expect(velocity.z).toBeCloseTo(-component, 10);
      expect(Math.hypot(velocity.x, velocity.z)).toBeCloseTo(WALK_SPEED, 10);
      expect(harness.player.getPlayerState()).toBe(harness.player.PlayerState.WALK);
