import { WORLD_CONFIG } from '../../../../../voxel-rpg/src/core/constants.js';

const DEFAULT_SEED = 1337;

const buildTerrain = (seed = DEFAULT_SEED) => {
  const parent = new THREE.Group();
  const rng = createRng(seed);
  const terrain = createTerrain({ rng, parent });
