      expect(terrain.group.children[0]).toBe(stoneMesh);
      expect(terrain.group.children[1]).toBe(fillMesh);
      expect(terrain.group.children[2]).toBe(topMesh);
      expect(topMesh).toBeInstanceOf(THREE.InstancedMesh);
      expect(fillMesh).toBeInstanceOf(THREE.InstancedMesh);
      expect(stoneMesh).toBeInstanceOf(THREE.InstancedMesh);

      for (const mesh of terrain.collisionMeshes) {
        expect(mesh.geometry).toBe(topMesh.geometry);
        expect(mesh.material).toBeInstanceOf(THREE.MeshLambertMaterial);
        expect(mesh.castShadow).toBe(false);
        expect(mesh.receiveShadow).toBe(true);
        expect(mesh.parent).toBe(terrain.group);
      }

      expect(topMesh.material.color.getHexString()).toBe('6ea54d');
      expect(fillMesh.material.color.getHexString()).toBe('6b4d2f');
      expect(stoneMesh.material.color.getHexString()).toBe('5e626b');
    });

    it('places one top instance at every cell and tints them with the terrain rng', () => {
      const { terrain } = buildTerrain();
      const [topMesh] = terrain.collisionMeshes;
      const { size, halfSize, cellSize, heights } = terrain;

      expect(topMesh.count).toBe(size * size);
      expect(topMesh.instanceColor).not.toBeNull();

      const indexes = [0, 1, size, 17 * size + 31, size * size - 1];
      for (const index of indexes) {
        const x = Math.floor(index / size);
        const z = index % size;
        const position = matrixTranslation(topMesh, index);
        expect(position.x).toBeCloseTo((x - halfSize) * cellSize, 5);
        expect(position.y).toBeCloseTo((heights[x][z] - 0.5) * cellSize, 5);
        expect(position.z).toBeCloseTo((z - halfSize) * cellSize, 5);

        const color = instanceColor(topMesh, index);
        expect(color.r).toBeGreaterThanOrEqual(0.33 * 0.85);
        expect(color.r).toBeLessThanOrEqual(0.33 * 1.03);
        expect(color.g).toBeGreaterThanOrEqual(0.62 * 0.85);
        expect(color.g).toBeLessThanOrEqual(0.62 * 1.03);
        expect(color.b).toBeGreaterThanOrEqual(0.25 * 0.85);
        expect(color.b).toBeLessThanOrEqual(0.25 * 1.03);
      }
    });

    it('places two stone layers in every column at the expected heights and colours', () => {
      const { terrain } = buildTerrain();
      const [, , stoneMesh] = terrain.collisionMeshes;
      const { size, halfSize, cellSize } = terrain;

      expect(stoneMesh.count).toBe(size * size * 2);
      expect(stoneMesh.instanceColor).not.toBeNull();

      for (const [x, z] of [[0, 0], [5, 9], [size - 1, size - 1]]) {
        const baseIndex = (x * size + z) * 2;
        for (let y = 0; y < 2; y += 1) {
          const position = matrixTranslation(stoneMesh, baseIndex + y);
          expect(position.x).toBeCloseTo((x - halfSize) * cellSize, 5);
          expect(position.y).toBeCloseTo((y + 0.5) * cellSize, 5);
          expect(position.z).toBeCloseTo((z - halfSize) * cellSize, 5);

          const color = instanceColor(stoneMesh, baseIndex + y);
          expect(color.r).toBeCloseTo(0.38 + y * 0.03, 5);
          expect(color.g).toBeCloseTo(0.39 + y * 0.03, 5);
          expect(color.b).toBeCloseTo(0.42 + y * 0.03, 5);
        }
      }
    });

    it('populates fill instances for every block above the two stone layers', () => {
      const { terrain } = buildTerrain();
      const [, fillMesh] = terrain.collisionMeshes;
      const { size, halfSize, cellSize, heights } = terrain;

      let requiredFillInstances = 0;
      for (let x = 0; x < size; x += 1) {
        for (let z = 0; z < size; z += 1) {
          requiredFillInstances += Math.max(0, heights[x][z] - 3);
        }
      }

      expect(requiredFillInstances).toBeGreaterThan(0);
      expect(fillMesh.count).toBeGreaterThanOrEqual(requiredFillInstances);
      expect(fillMesh.instanceColor).not.toBeNull();

      let fillIndex = 0;
      for (let x = 0; x < size; x += 1) {
        for (let z = 0; z < size; z += 1) {
          for (let y = 2; y < heights[x][z] - 1; y += 1) {
            const position = matrixTranslation(fillMesh, fillIndex);
            expect(position.x).toBeCloseTo((x - halfSize) * cellSize, 5);
            expect(position.y).toBeCloseTo((y + 0.5) * cellSize, 5);
            expect(position.z).toBeCloseTo((z - halfSize) * cellSize, 5);

            const color = instanceColor(fillMesh, fillIndex);
            expect(color.r).toBeCloseTo(0.42, 5);
            expect(color.g).toBeCloseTo(0.28 + y * 0.01, 5);
            expect(color.b).toBeCloseTo(0.17, 5);
            fillIndex += 1;
          }
        }
      }
      expect(fillIndex).toBe(requiredFillInstances);
    });
  });
});

